const ctx = $('Input').first().json;
const b = ctx.brief ?? {}; const sc = ctx.scorecard ?? {}; const te = ctx.tax_estimate ?? {};
const money = (n) => n == null ? 'TBD' : ('$' + Math.round(n).toLocaleString('en-US'));
const pct = (n) => n == null ? 'TBD' : ((n * 100).toFixed(1) + '%');
const q1 = (te.quarterly_payments ?? [])[0] ?? {};
const strategies = (b.strategy_opportunities ?? []).slice(0, 3).map(s => s.strategy + ' (' + money(s.estimated_savings) + ')').join('\n') || 'Under review';
const repl = {
  CLIENT_NAME: ctx.client_name ?? '', MEETING_DATE: ctx.meeting_date ?? '',
  EXEC_SUMMARY: (b.executive_summary ?? []).join('\n'),
  REVENUE: money(sc.revenue?.current), REVENUE_CHANGE: pct((sc.revenue?.pct_change ?? 0) / 100),
  TAKE_HOME: money(sc.owner_take_home?.current), NET_MARGIN: pct(sc.net_margin?.current),
  TAX_SAVINGS: money(te.entity_comparison?.savings),
  Q_FED: money(q1.federal), Q_STATE: money(q1.state), Q_DUE: q1.due_date ?? 'TBD',
  STRATEGIES: strategies,
  NEXT_90: (b.key_talking_points ?? []).slice(0, 3).join('\n'),
};
const requests = Object.entries(repl).map(([k, v]) => ({ replaceAllText: {
  containsText: { text: '{{' + k + '}}', matchCase: true }, replaceText: String(v) } }));
return [{ json: { presentationId: $json.id, requests } }];

const ctx = $('Input').first().json;
const pid = $('Build replaceAllText requests').first().json.presentationId;
return [{ json: { ...ctx, deck_id: pid, deck_url: 'https://docs.google.com/presentation/d/' + pid + '/edit' } }];
